-- Common catalogue sizes. Idempotent: replace the previous size note before appending the current one.
UPDATE sites SET desc = rtrim(substr(desc, 1, CASE WHEN instr(desc, ' Common sizes:') > 0 THEN instr(desc, ' Common sizes:') - 1 ELSE length(desc) END)) || ' Common sizes: 15×25, 17×30, 20×30, 25×35, 28×42, 32×43, 35×50, 38×51, 40×55, 45×60, 55×65, 55×75, 60×84 and 80×100 cm; add approximately 5 cm for the sealing flap.' WHERE catelog_name='Courier Packaging Bags' AND id IN (1,5);
